package com.techgenius.tvoslauncher;
import java.nio.file.*;import java.util.*;
public final class LiveTvDataTest {
 static int checks;static void check(boolean ok,String why){checks++;if(!ok)throw new AssertionError(why);}
 public static void main(String[] args)throws Exception{
  String text="\uFEFF#EXTM3U x-tvg-url=\"https://example.org/epg.xml\"\n#EXTINF:-1 tvg-id=\"Real.test@SD\" tvg-logo=\"https://example.org/logo.png\" group-title=\"News;General\",قناة اختبار، خبر\n#EXTVLCOPT:http-referrer=https://example.org/\nhttps://example.org/live.m3u8\n#EXTINF:-1 tvg-id=\"Real.test@HD\",Channel HD\nhttps://example.org/live-hd.m3u8\n#EXTINF:-1 tvg-id=\"Real.test@HD\",Duplicate\nhttps://example.org/live-hd.m3u8\n";
  LiveTvData.Playlist p=LiveTvData.parse(text);check(p.channels.size()==1,"Stable channel dedup");check(p.channels.get(0).streams.size()==2,"Keep actual alternate sources");check(p.epg.equals("https://example.org/epg.xml"),"XMLTV header");check(p.channels.get(0).streams.get(0).referrer.equals("https://example.org/"),"Source referrer");check(p.channels.get(0).name.equals("قناة اختبار، خبر"),"Unicode title");check(LiveTvData.search(p.channels,"قناه").isEmpty(),"Do not replace unrelated letters");check(LiveTvData.search(p.channels,"قناة").size()==1,"Arabic search");check(LiveTvData.normalize("أَخْبَار").equals("اخبار"),"Arabic search normalization");
  check(!LiveTvData.allowed("beIN SPORTS 1","https://example.org/a"),"No invented beIN subscription");check(!LiveTvData.allowed("OSN Movies","https://example.org/a"),"No OSN");check(!LiveTvData.allowed("TV","http://149.100.11.252:8000/play/x"),"Do not use unknown IP restreams");check(!LiveTvData.allowed("TV","https://example.org/get.php?username=x&password=y"),"No subscription credentials");check(LiveTvData.allowed("Public broadcaster","https://example.org/master.m3u8"),"Public source");
  check(!LiveTvData.hasArabic("eng;jpn"),"Name/country do not prove Arabic audio");check(LiveTvData.hasArabic("ara;jpn"),"ISO639 Arabic");check(LiveTvData.hasArabic("ar-SA"),"Arabic region tag");check(!LiveTvData.hasArabic("Arabic TV"),"Do not infer language from display name");
  String drm="#EXTM3U\n#EXTINF:-1 tvg-id=\"test\",A\n#KODIPROP:inputstream.adaptive.license_key=secret\nhttps://example.org/drm.mpd\n";check(LiveTvData.parse(drm).channels.isEmpty(),"No DRM key injection");boolean bad=false;try{LiveTvData.parse("<html>failure</html>");}catch(Exception e){bad=true;}check(bad,"Reject a non-playlist error response");
  LiveTvData.Channel c=LiveTvData.Channel.from(p.channels.get(0).json());check(c.key().equals("Real.test")&&c.streams.size()==2,"Persistent channel serialization");Map<String,LiveTvData.Meta> meta=new HashMap<>();LiveTvData.Meta m=new LiveTvData.Meta();m.id=c.id;m.name="Source channel";m.arabic="اسم عربي";m.country="JP";m.categories="animation";meta.put(m.id,m);Map<String,String> langs=new HashMap<>();langs.put("Real.test@SD","ara");List<LiveTvData.Channel> enriched=LiveTvData.enrich(Arrays.asList(c),meta,langs,5);check(enriched.size()==1&&c.name.equals("اسم عربي")&&c.arabicDeclared(),"Source metadata and Arabic priority");m.blocked=true;check(LiveTvData.enrich(Arrays.asList(c),meta,langs,2).isEmpty(),"Closed/adult source blocked");
  for(String file:args){LiveTvData.Playlist real=LiveTvData.parse(new String(Files.readAllBytes(Paths.get(file)),java.nio.charset.StandardCharsets.UTF_8));check(!real.channels.isEmpty(),"Live catalogue fixture "+file);Set<String> ids=new HashSet<>();for(LiveTvData.Channel n:real.channels){check(ids.add(n.key()),"Dedup real source");for(LiveTvData.Endpoint e:n.streams)check(LiveTvData.allowed(n.name,e.url),"Allowed public source");}}
  System.out.println("LIVE_TV_DATA_OK: "+checks+" checks");
 }
}
